    import { statisticProductListApi } from '@/api/statistic';
	import { cascaderListApi } from '@/api/product'
    import goodsDetail from "../components/goodsDetail";
    import { formatDate } from '@/utils/validate';
    export default {
        name: "productRanking",
        components: {
            goodsDetail
        },
        data() {
            return {
                validateFun:this.$validateFun,
                // options: this.$timeOptions,
				props: { emitPath: false, multiple: true, checkStrictly: true },
				cateData:[],
				options: {
				  shortcuts: [
				    {
				      text: "今天",
				      value() {
				        const end = new Date();
				        const start = new Date();
				        start.setTime(
				          new Date(
				            new Date().getFullYear(),
				            new Date().getMonth(),
				            new Date().getDate()
				          )
				        );
				        return [start, end];
				      },
				    },
				    {
				      text: "昨天",
				      value() {
				        const end = new Date();
				        const start = new Date();
				        start.setTime(
				          start.setTime(
				            new Date(
				              new Date().getFullYear(),
				              new Date().getMonth(),
				              new Date().getDate() - 1
				            )
				          )
				        );
				        end.setTime(
				          end.setTime(
				            new Date(
				              new Date().getFullYear(),
				              new Date().getMonth(),
				              new Date().getDate() - 1
				            )
				          )
				        );
				        return [start, end];
				      },
				    },
				    {
				      text: "最近7天",
				      value() {
				        const end = new Date();
				        const start = new Date();
				        start.setTime(
				          start.setTime(
				            new Date(
				              new Date().getFullYear(),
				              new Date().getMonth(),
				              new Date().getDate() - 6
				            )
				          )
				        );
				        return [start, end];
				      },
				    },
				    {
				      text: "最近30天",
				      value() {
				        const end = new Date();
				        const start = new Date();
				        start.setTime(
				          start.setTime(
				            new Date(
				              new Date().getFullYear(),
				              new Date().getMonth(),
				              new Date().getDate() - 29
				            )
				          )
				        );
				        return [start, end];
				      },
				    },
					{
					  text: "上月",
					  value() {
					    const end = new Date();
					    const start = new Date();
						const day = new Date(start.getFullYear(), start.getMonth(), 0).getDate();
					    start.setTime(
					      start.setTime(
					        new Date(new Date().getFullYear(), new Date().getMonth()-1, 1)
					      )
					    );
						end.setTime(
						  end.setTime(
						    new Date(new Date().getFullYear(), new Date().getMonth()-1, day)
						  )
						);
					    return [start, end];
					  },
					},
				    {
				      text: "本月",
				      value() {
				        const end = new Date();
				        const start = new Date();
				        start.setTime(
				          start.setTime(
				            new Date(new Date().getFullYear(), new Date().getMonth(), 1)
				          )
				        );
				        return [start, end];
				      },
				    },
				    {
				      text: "本年",
				      value() {
				        const end = new Date();
				        const start = new Date();
				        start.setTime(
				          start.setTime(new Date(new Date().getFullYear(), 0, 1))
				        );
				        return [start, end];
				      },
				    },
				  ],
				},
                name: '近30天',
                timeVal: [],
                dataTime: '',
                formValidate: {
                    limit: 10,
                    page: 1,
                    sort: 'visit',
                    data: '',
					cate_id: [],
                },
                loading: false,
                tabList: [],
                total: 0,
                columns4: [
                    {
                        title: '商品图片',
                        slot: 'image',
                        minWidth: 80
                    },
                    {
                        title: '商品名称',
                        width: 180,
                        key: 'store_name'
                    },
                    {
                        title: '浏览量',
                        key: 'visit',
                        minWidth: 100
                    },
                    {
                        title: '访客数',
                        key: 'user',
                        minWidth: 100
                    },
                    {
                        title: '加购件数',
                        key: 'cart',
                        minWidth: 100
                    },
                    {
                        title: '下单件数',
                        key: 'orders',
                        minWidth: 100
                    },
                    {
                        title: '支付件数',
                        key: 'pay',
                        minWidth: 100
                    },
                    {
                        title: '支付金额',
                        key: 'price',
                        minWidth: 100
                    },
                    {
                        title: '毛利率(%)',
                        slot: 'profit',
                        minWidth: 100
                    },
                    {
                        title: '收藏数',
                        key: 'collect',
                        minWidth: 100
                    },
                    {
                        title: '访客-支付转化率(%)',
                        slot: 'changes',
                        minWidth: 120
                    }
                    // {
                    //     title: '操作',
                    //     slot: 'action',
                    //     fixed: 'right',
                    //     minWidth: 80
                    // }
                ],
                goodsId: "",
                isProductBox: false,
                list: [
                    {
                        val:"visit",
                        name:'浏览量'
                    },
                    {
                        val:"user",
                        name:'访客数'
                    },
                    {
                        val:"cart",
                        name:'加购件数'
                    },
                    {
                        val:"orders",
                        name:'下单件数'
                    },
                    {
                        val:"price",
                        name:'支付金额'
                    },
                    {
                        val:"profit",
                        name:'毛利率'
                    },
                    {
                        val:"collect",
                        name:'收藏数'
                    },
                    {
                        val:"changes",
                        name:'访客-支付转化率'
                    }
                ]
            }
        },
        created() {
            const end = new Date()
            const start = new Date()
            start.setTime(start.setTime(new Date(new Date().getFullYear(), new Date().getMonth(), new Date().getDate() - 29)));
            this.timeVal = [start, end]
            this.formValidate.data = formatDate(start, 'yyyy/MM/dd')+ '-'+ formatDate(end, 'yyyy/MM/dd');
        },
        mounted() {
            this.getList();
			this.goodsCategory();
        },
        methods: {
			// 商品分类；
			goodsCategory() {
			  cascaderListApi(1)
			      .then((res) => {
			        this.cateData = res.data;
			      })
			      .catch((res) => {
			        this.$Message.error(res.msg);
			      });
			},
            // 具体日期
            onchangeTime (e) {
                this.timeVal = e
                this.formValidate.data = this.timeVal.join('-');
                this.name = this.formValidate.data;
            },
            changeMenu(name){
                this.formValidate.sort = name;
                this.getList();
            },
            // 列表
            getList () {
                this.loading = true
                statisticProductListApi(this.formValidate).then(async res => {
                    let data = res.data;
                    this.tabList = data;
                    this.loading = false;
                }).catch(res => {
                    this.loading = false;
                    this.$Message.error(res.msg);
                })
            },
            look(row){
                this.goodsId = row.product_id;
                this.isProductBox = true
            }
        }
    }
